import{_ as t,o as i,c as s,an as r}from"./chunks/framework.C1Zpw0WN.js";const p=JSON.parse('{"title":"Regridding","description":"","frontmatter":{},"headers":[],"relativePath":"preprocessing/regridding.md","filePath":"preprocessing/regridding.md","lastUpdated":null}'),a={name:"preprocessing/regridding.md"};function n(o,e,d,l,h,c){return i(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="Regridding" tabindex="-1">Regridding <a class="header-anchor" href="#Regridding" aria-label="Permalink to &quot;Regridding {#Regridding}&quot;">​</a></h1><p>Whenever the preprocessor source mesh and target mesh differ, mass fields move through a <strong>conservative regridder</strong> built on top of <a href="https://github.com/JuliaGeo/ConservativeRegridding.jl" target="_blank" rel="noreferrer">ConservativeRegridding.jl</a>. This page covers the public surface, the JLD2 weights cache, and the mass-consistency correction the preprocessor applies after every regrid.</p><h2 id="Public-API" tabindex="-1">Public API <a class="header-anchor" href="#Public-API" aria-label="Permalink to &quot;Public API {#Public-API}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">regridder </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> build_regridder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(src_mesh, dst_mesh;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                             normalize </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                             cache_dir </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nothing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># opt-in caching</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">apply_regridder!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dst, regridder, src)</span></span></code></pre></div><ul><li><p><strong><code>build_regridder</code></strong> returns a wrapped <code>ConservativeRegridding.Regridder</code> carrying <code>(intersections, dst_areas, src_areas)</code>.</p></li><li><p><strong><code>apply_regridder!</code></strong> does an in-place column-by-column regrid for any n-D source where the leading dimension is the horizontal one (3-D <code>(ncell_src, Nz)</code> → <code>(ncell_dst, Nz)</code>, 2-D <code>(ncell_src,)</code> → <code>(ncell_dst,)</code>).</p></li><li><p><code>normalize = true</code> scales weights so the largest intersection gets weight 1 — useful for diagnostic plots, <strong>never</strong> for mass fields.</p></li><li><p><code>cache_dir = nothing</code> (the default) skips the JLD2 cache and rebuilds the weights every call. Pass an absolute path (e.g. <code>~/.cache/AtmosTransport/cr_regridding</code>) to opt in. The preprocessing TOMLs set this via <code>[grid] regridder_cache_dir</code>.</p></li></ul><p>Both functions live in <code>src/Regridding/weights_io.jl</code>.</p><h2 id="Supported-topology-pairs" tabindex="-1">Supported topology pairs <a class="header-anchor" href="#Supported-topology-pairs" aria-label="Permalink to &quot;Supported topology pairs {#Supported-topology-pairs}&quot;">​</a></h2><p>The same generic API covers every (source, target) pair:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Source ↓ Target →</th><th style="text-align:right;">LatLon</th><th style="text-align:right;">Reduced Gaussian</th><th style="text-align:right;">CubedSphere</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>LatLon</strong></td><td style="text-align:right;">identity (or LL→LL regrid)</td><td style="text-align:right;"><strong>per-ring conservative</strong> (LL→RG specifically uses the per-ring R-tree workaround below)</td><td style="text-align:right;">conservative</td></tr><tr><td style="text-align:right;"><strong>Reduced Gaussian</strong></td><td style="text-align:right;">conservative (generic path)</td><td style="text-align:right;">identity (when the rings match)</td><td style="text-align:right;">conservative</td></tr><tr><td style="text-align:right;"><strong>CubedSphere</strong></td><td style="text-align:right;">conservative</td><td style="text-align:right;">conservative</td><td style="text-align:right;">identity</td></tr></tbody></table><p>Same-mesh paths (LL → LL with identical <code>(Nx, Ny)</code>, CS → CS with identical <code>Nc</code> and panel convention, etc.) automatically resolve to <strong><code>IdentityRegrid</code></strong> through the structural-equivalence check described below.</p><h2 id="IdentityRegrid-—-zero-overhead-passthrough" tabindex="-1"><code>IdentityRegrid</code> — zero-overhead passthrough <a class="header-anchor" href="#IdentityRegrid-—-zero-overhead-passthrough" aria-label="Permalink to &quot;\`IdentityRegrid\` — zero-overhead passthrough {#IdentityRegrid-—-zero-overhead-passthrough}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># build_regridder returns an IdentityRegrid when meshes_equivalent(src, dst);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># direct construction is also fine:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">regridder </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> IdentityRegrid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mesh)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">apply_regridder!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dst, regridder, src)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># equivalent to copyto!(dst, src)</span></span></code></pre></div><p>Used heavily by the <strong>GEOS-CS → CS passthrough</strong> preprocessing path where the source and target meshes are structurally equivalent (same type, same shape parameters, same panel convention). The equivalence check is <code>meshes_equivalent(src, dst)</code> in <code>src/Regridding/identity_regrid.jl</code>, not a Julia object-identity (<code>===</code>) test, so two independently constructed meshes with the same parameters still resolve to the identity path. Type-stable, zero allocation, no <code>if</code> branch in the hot loop. Any future grid type that defines <code>meshes_equivalent</code> for itself plugs into <code>IdentityRegrid</code> without code changes.</p><h2 id="The-JLD2-weights-cache" tabindex="-1">The JLD2 weights cache <a class="header-anchor" href="#The-JLD2-weights-cache" aria-label="Permalink to &quot;The JLD2 weights cache {#The-JLD2-weights-cache}&quot;">​</a></h2><p>Building the conservative-regridder weights for a real grid pair is the single most expensive thing the preprocessor does on day 1 (seconds for low resolution, minutes for C180 / O320). The cache makes day 2 onward effectively free.</p><ul><li><p><strong>Cache directory:</strong> opt-in via the <code>cache_dir</code> kwarg on <code>build_regridder</code> (the preprocessing TOMLs set <code>[grid] regridder_cache_dir = &quot;~/.cache/AtmosTransport/cr_regridding&quot;</code>).</p></li><li><p><strong>Cache key:</strong> SHA-1 of a tuple containing:</p><ul><li><p>source and destination mesh <strong>type</strong> + shape parameters (<code>(Nx, Ny)</code>, <code>Nc</code>, <code>nlon_per_ring</code>, panel convention, …),</p></li><li><p>source and destination radii (Earth radius is stable, but the cache key still includes it),</p></li><li><p><code>normalize</code> flag.</p></li></ul></li><li><p><strong>Cache file:</strong> <code>regridder_&lt;SHA1&gt;.jld2</code>, JLD2-loaded (not memory- mapped) on subsequent calls. JLD2 load is ~10 ms; rebuilding the weights is seconds-to-minutes, so the cache is the difference between &quot;instant&quot; and &quot;wait&quot; on warm runs.</p></li></ul><p>The cache key intentionally does <strong>not</strong> include source / target data — it&#39;s purely geometric. Two preprocessing runs over different days share the same regridder JLD2.</p><h2 id="Per-ring-regrid-for-LatLon-ReducedGaussian" tabindex="-1">Per-ring regrid for <code>LatLon → ReducedGaussian</code> <a class="header-anchor" href="#Per-ring-regrid-for-LatLon-ReducedGaussian" aria-label="Permalink to &quot;Per-ring regrid for \`LatLon → ReducedGaussian\` {#Per-ring-regrid-for-LatLon-ReducedGaussian}&quot;">​</a></h2><p>The generic <code>ConservativeRegridding.MultiTreeWrapper</code> path has a known degeneracy on reduced-Gaussian meshes (some ring boundaries get pruned because of LCM segmentation overlap). For the <strong>LL → RG</strong> case specifically, <code>weights_io.jl</code> builds <strong>one R-tree per ring</strong> and stitches the results; the reverse direction (RG → anything) uses the generic conservative path. The per-ring workaround is the reason the RG-target preprocessing takes a bit longer to build than equivalent LL or CS targets at first run.</p><h2 id="Mass-closure-across-topologies" tabindex="-1">Mass closure across topologies <a class="header-anchor" href="#Mass-closure-across-topologies" aria-label="Permalink to &quot;Mass closure across topologies {#Mass-closure-across-topologies}&quot;">​</a></h2><p>Conservative regridding preserves total mass exactly. The earlier &quot;per-level mass correction&quot; helper (<code>_enforce_perlevel_mass_consistency!</code>) has been <strong>removed</strong> — it was a band-aid for a regrid path that did not respect the extensive / intensive distinction.</p><p>The current path uses <code>regrid_3d_to_cs_panels!</code> with an <code>ExtensiveCellField()</code> flag on both sides of the regrid. The extensive-on-both-sides contract converts through density, so the spatial distribution is preserved by construction and the per-level mass identity holds to floating-point tolerance without any post-regrid correction.</p><p>If you are extending the regridding subsystem with a new mesh pair and the write-time replay gate fails because the per-level totals drift: the first check is whether you are using <code>ExtensiveCellField()</code> consistently — not whether you need to re-introduce a post-regrid correction.</p><h2 id="What&#39;s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#What&#39;s-next" aria-label="Permalink to &quot;What&amp;#39;s next {#What&#39;s-next}&quot;">​</a></h2><ul><li><p><a href="/AtmosTransport.jl/stable/preprocessing/conventions#Conventions-cheat-sheet">Conventions cheat sheet</a> — units, replay tolerances, level orientation, panel conventions.</p></li><li><p><em>Tutorials</em> — once the bundle artifact lands, a Literate tutorial will demo a non-trivial cross-topology regrid (ERA5 spectral → CS).</p></li></ul>`,25)])])}const u=t(a,[["render",n]]);export{p as __pageData,u as default};
